import type { ReactNode } from 'react'
import { useId, useState } from 'react'
import './styles.css'

export interface NavigationItem {
  value: string
  label: ReactNode
}

export interface NavigationProps {
  /** Accessible name of the navigation landmark. */
  label: string
  items: NavigationItem[]
  header?: ReactNode
  activeValue?: string
  defaultValue?: string
  onSelect?: (value: string) => void
  /**
   * How many destinations stay in the compact tab bar. Extra items go behind
   * More on compact and list in full in the sidebar form. Capped at 4 so the
   * bar never exceeds four pins + More.
   */
  maxCompactItems?: number
  moreLabel?: string
  /** Render the tablet collapse toggle (hidden by CSS on compact and desktop). */
  collapsible?: boolean
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  expandLabel?: string
  collapseLabel?: string
  className?: string
}

const MAX_COMPACT_PINS = 4

export function splitNavigationItems(items: NavigationItem[], maxCompactItems = MAX_COMPACT_PINS) {
  const cap = Math.min(Math.max(maxCompactItems, 1), MAX_COMPACT_PINS)
  if (items.length <= cap) return { compact: items, overflow: [] as NavigationItem[] }
  return { compact: items.slice(0, cap), overflow: items.slice(cap) }
}

export function Navigation({
  label,
  items,
  header,
  activeValue,
  defaultValue,
  onSelect,
  maxCompactItems = MAX_COMPACT_PINS,
  moreLabel = 'More',
  collapsible = true,
  collapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  expandLabel = 'Expand navigation',
  collapseLabel = 'Collapse navigation',
  className,
}: NavigationProps) {
  const [internalCollapsed, setInternalCollapsed] = useState(defaultCollapsed)
  const [internalActive, setInternalActive] = useState(defaultValue ?? items[0]?.value)
  const [moreOpen, setMoreOpen] = useState(false)
  const isCollapsed = collapsed ?? internalCollapsed
  const current = activeValue ?? internalActive
  const { compact, overflow } = splitNavigationItems(items, maxCompactItems)
  const overflowActive = overflow.some((item) => item.value === current)
  const listId = useId()
  const overflowId = useId()

  function requestCollapsedChange(next: boolean) {
    if (collapsed === undefined) setInternalCollapsed(next)
    onCollapsedChange?.(next)
  }

  function select(value: string) {
    if (activeValue === undefined) setInternalActive(value)
    onSelect?.(value)
    setMoreOpen(false)
  }

  const classes = ['cu-navigation', isCollapsed && 'cu-navigation--collapsed', className]
    .filter(Boolean)
    .join(' ')

  function renderItem(item: NavigationItem) {
    return (
      <li key={item.value} className="cu-navigation__entry">
        <button
          type="button"
          className="cu-navigation__item"
          aria-current={current === item.value ? 'page' : undefined}
          aria-label={typeof item.label === 'string' ? item.label : undefined}
          onClick={() => select(item.value)}
        >
          <span className="cu-navigation__label">{item.label}</span>
        </button>
      </li>
    )
  }

  return (
    <nav
      className={classes}
      aria-label={label}
      data-ai-role="navigation"
      data-ai-intent="navigate-sections"
      data-ai-state={isCollapsed ? 'collapsed' : 'expanded'}
      data-more={moreOpen ? 'open' : 'closed'}
      onKeyDown={(event) => {
        if (event.key === 'Escape') setMoreOpen(false)
      }}
    >
      <div className="cu-navigation__frame">
        {header ? <div className="cu-navigation__header">{header}</div> : null}
        <ul id={listId} className="cu-navigation__list">
          {compact.map(renderItem)}
          {overflow.length > 0 ? (
            <li className="cu-navigation__overflow">
              <ul id={overflowId} className="cu-navigation__overflow-list">
                {overflow.map(renderItem)}
              </ul>
            </li>
          ) : null}
          {overflow.length > 0 ? (
            <li className="cu-navigation__entry cu-navigation__entry--more">
              <button
                type="button"
                className="cu-navigation__item"
                aria-expanded={moreOpen}
                aria-controls={overflowId}
                aria-current={overflowActive ? 'page' : undefined}
                onClick={() => setMoreOpen((open) => !open)}
              >
                <span className="cu-navigation__label">{moreLabel}</span>
              </button>
            </li>
          ) : null}
        </ul>
        {collapsible ? (
          <button
            type="button"
            className="cu-navigation__toggle"
            aria-expanded={!isCollapsed}
            aria-controls={listId}
            aria-label={isCollapsed ? expandLabel : collapseLabel}
            onClick={() => requestCollapsedChange(!isCollapsed)}
          >
            <span
              aria-hidden="true"
              className="cu-navigation__toggle-icon"
              data-direction={isCollapsed ? 'expand' : 'collapse'}
            >
              <svg viewBox="0 0 24 24" className="cu-navigation__toggle-svg">
                <path
                  d={isCollapsed ? 'M9 6l6 6-6 6' : 'M15 6l-6 6 6 6'}
                  fill="none"
                  stroke="currentColor"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                />
              </svg>
            </span>
            <span className="cu-navigation__label">{isCollapsed ? expandLabel : collapseLabel}</span>
          </button>
        ) : null}
      </div>
    </nav>
  )
}

/*
 * Three-end Navigation: one landmark, one item list, CSS morphs the chrome.
 * Compact (mobile-first) is a block-end tab bar. Named container `app-shell`
 * (when composed) or own container `navigation` (standalone) upgrades the
 * inner frame to a collapsible rail at 48rem and a persistent sidebar at 80rem.
 * The root is the query container; only descendants are restyled (规范 §2).
 */
.cu-navigation {
  color: var(--cu-color-fg-default);
  container-name: navigation;
  container-type: inline-size;
  inline-size: 100%;
  block-size: 100%;
  contain: layout style;
}

/* Compact base: horizontal tab bar filling the shell's block-end grid cell. */
.cu-navigation__frame {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  position: relative;
  inline-size: 100%;
  padding-block-end: env(safe-area-inset-bottom, 0px);
  border-block-start: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(
    --cu-color-background-translucent,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
}

.cu-navigation__header,
.cu-navigation__toggle {
  display: none;
}

.cu-navigation__list {
  display: flex;
  flex: 1;
  flex-direction: row;
  align-items: stretch;
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-navigation__entry {
  display: flex;
  flex: 1;
  min-inline-size: 0;
}

.cu-navigation__item {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-1);
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: none;
  border-block-start: 2px solid transparent;
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  font-size: 0.875rem;
  cursor: pointer;
}

.cu-navigation__item[aria-current='page'] {
  border-block-start-color: var(--cu-color-palette-brand);
  color: var(--cu-color-palette-brand);
  font-weight: var(--cu-typography-weight-semibold, 600);
}

.cu-navigation__item:focus-visible,
.cu-navigation__toggle:focus-visible {
  outline: 2px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}

@media (hover: hover) {
  .cu-navigation__item:hover:not([aria-current='page']),
  .cu-navigation__toggle:hover {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

.cu-navigation__toggle-icon {
  display: inline-flex;
  inline-size: 1em;
  block-size: 1em;
  flex: none;
}

.cu-navigation__toggle-svg {
  inline-size: 100%;
  block-size: 100%;
}

[dir='rtl'] .cu-navigation__toggle-icon {
  transform: scaleX(-1);
}

.cu-navigation__label {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Compact: overflow destinations live behind More; the same nodes list in the sidebar form. */
.cu-navigation__overflow {
  display: none;
}

.cu-navigation[data-more='open'] .cu-navigation__overflow {
  display: block;
  position: absolute;
  inset-inline: 0;
  inset-block-end: 100%;
  z-index: 6;
  max-block-size: min(60vh, 24rem);
  overflow: auto;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(
    --cu-color-background-elevated,
    var(--cu-color-background-default)
  );
  box-shadow: var(--cu-shadow-lg, var(--cu-shadow-md, none));
}

.cu-navigation__overflow-list {
  display: flex;
  flex-direction: column;
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-navigation[data-more='open'] .cu-navigation__overflow .cu-navigation__item {
  flex-direction: row;
  justify-content: start;
  font-size: inherit;
  text-align: start;
  border-block-start: none;
  border-radius: var(--cu-radius-sm);
}

.cu-navigation__entry--more {
  display: flex;
  flex: 1;
  min-inline-size: 0;
}

/* Very narrow compact bars shrink labels (own container, not the viewport). */
@container navigation (max-width: 20rem) {
  .cu-navigation__item {
    font-size: 0.75rem;
    padding-inline: var(--cu-space-1);
  }
}

/*
 * Sidebar form. Duplicated for standalone (`navigation`) and in-shell
 * (`app-shell`): the in-shell nav cell is 12rem/16rem, so the component's
 * own container would stay compact unless the shell named container wins.
 */
@container navigation (min-width: 48rem) {
  .cu-navigation__frame {
    flex-direction: column;
    gap: var(--cu-space-2);
    min-block-size: 100%;
    padding-block: var(--cu-space-3);
    padding-inline: var(--cu-space-2);
    padding-block-end: var(--cu-space-3);
    border-block-start: none;
    border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
    background: var(--cu-color-background-elevated, var(--cu-color-background-default));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .cu-navigation__header {
    display: block;
    padding-block: var(--cu-space-1);
    padding-inline: var(--cu-space-2);
    font-weight: var(--cu-typography-weight-semibold, 600);
  }

  .cu-navigation__list {
    flex-direction: column;
    gap: var(--cu-space-1);
    overflow: auto;
  }

  .cu-navigation__entry {
    flex: none;
  }

  .cu-navigation__item {
    flex-direction: row;
    justify-content: start;
    gap: var(--cu-space-2);
    padding-block: var(--cu-space-2);
    border-block-start: none;
    border-radius: var(--cu-radius-sm);
    font-size: inherit;
    text-align: start;
  }

  .cu-navigation__item[aria-current='page'] {
    background: color-mix(in srgb, var(--cu-color-fg-default) 6%, transparent);
  }

  .cu-navigation__toggle {
    display: flex;
    align-items: center;
    gap: var(--cu-space-2);
    min-block-size: var(--cu-touch-target-min);
    padding-block: var(--cu-space-2);
    padding-inline: var(--cu-space-2);
    border: var(--cu-border-width-default, 1px) solid var(--cu-color-border-default);
    border-radius: var(--cu-radius-sm);
    background: transparent;
    color: var(--cu-color-fg-default);
    font: inherit;
    cursor: pointer;
  }

  .cu-navigation--collapsed .cu-navigation__label {
    display: none;
  }

  .cu-navigation--collapsed .cu-navigation__item,
  .cu-navigation--collapsed .cu-navigation__toggle {
    justify-content: center;
  }

  .cu-navigation .cu-navigation__overflow,
  .cu-navigation[data-more='open'] .cu-navigation__overflow {
    display: block;
    position: static;
    inset: auto;
    max-block-size: none;
    overflow: visible;
    padding: 0;
    border: none;
    background: transparent;
    box-shadow: none;
  }

  .cu-navigation__overflow-list {
    gap: var(--cu-space-1);
  }

  .cu-navigation__entry--more {
    display: none;
  }
}

@container navigation (min-width: 80rem) {
  .cu-navigation__toggle {
    display: none;
  }
}

@container app-shell (min-width: 48rem) {
  .cu-navigation__frame {
    flex-direction: column;
    gap: var(--cu-space-2);
    min-block-size: 100%;
    padding-block: var(--cu-space-3);
    padding-inline: var(--cu-space-2);
    padding-block-end: var(--cu-space-3);
    border-block-start: none;
    border-inline-end: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
    background: var(--cu-color-background-elevated, var(--cu-color-background-default));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .cu-navigation__header {
    display: block;
    padding-block: var(--cu-space-1);
    padding-inline: var(--cu-space-2);
    font-weight: var(--cu-typography-weight-semibold, 600);
  }

  .cu-navigation__list {
    flex-direction: column;
    gap: var(--cu-space-1);
    overflow: auto;
  }

  .cu-navigation__entry {
    flex: none;
  }

  .cu-navigation__item {
    flex-direction: row;
    justify-content: start;
    gap: var(--cu-space-2);
    padding-block: var(--cu-space-2);
    border-block-start: none;
    border-radius: var(--cu-radius-sm);
    font-size: inherit;
    text-align: start;
  }

  .cu-navigation__item[aria-current='page'] {
    background: color-mix(in srgb, var(--cu-color-fg-default) 6%, transparent);
  }

  .cu-navigation__toggle {
    display: flex;
    align-items: center;
    gap: var(--cu-space-2);
    min-block-size: var(--cu-touch-target-min);
    padding-block: var(--cu-space-2);
    padding-inline: var(--cu-space-2);
    border: var(--cu-border-width-default, 1px) solid var(--cu-color-border-default);
    border-radius: var(--cu-radius-sm);
    background: transparent;
    color: var(--cu-color-fg-default);
    font: inherit;
    cursor: pointer;
  }

  .cu-navigation--collapsed .cu-navigation__label {
    display: none;
  }

  .cu-navigation--collapsed .cu-navigation__item,
  .cu-navigation--collapsed .cu-navigation__toggle {
    justify-content: center;
  }

  .cu-navigation .cu-navigation__overflow,
  .cu-navigation[data-more='open'] .cu-navigation__overflow {
    display: block;
    position: static;
    inset: auto;
    max-block-size: none;
    overflow: visible;
    padding: 0;
    border: none;
    background: transparent;
    box-shadow: none;
  }

  .cu-navigation__overflow-list {
    gap: var(--cu-space-1);
  }

  .cu-navigation__entry--more {
    display: none;
  }
}

@container app-shell (min-width: 80rem) {
  .cu-navigation__toggle {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-navigation,
  .cu-navigation__item,
  .cu-navigation__toggle {
    transition-duration: 0.01ms;
  }
}
